styl:
.iq-hero-copy{width:100%}
.iq-hero-title{color:{{ title_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:{{ title_size }}px;font-weight:700;line-height:{{ title_line_height }}px;margin:0;padding:{{ title_padding }};word-break:break-word}
.iq-hero-body{color:{{ body_color }};font-family:Helvetica,Arial,sans-serif!important;font-size:{{ body_size }}px;font-style:normal;font-weight:400;line-height:{{ body_line_height }}px;margin:0;padding:0}
@media screen and (max-width:600px){.iq-hero-title{font-size:26px!important;line-height:32px!important}.iq-hero-body{padding-right:0!important}}
